<!doctype html><html lang="{{app()->getLocale()}}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clima en Loreto · NavegaYA</title><style>
body{margin:0;background:#f4f7f8;color:#173b4b;font-family:DM Sans,Arial,sans-serif}.weather{max-width:1120px;margin:24px auto 70px;padding:0 24px}.hero{padding:38px;border-radius:24px;background:linear-gradient(125deg,#104b68,#168bb5);color:#fff;box-shadow:0 18px 38px #145b7825}.hero small{color:#b9edff;font-weight:850;letter-spacing:.13em}.hero h1{margin:8px 0;font-size:42px}.hero p{max-width:680px;margin:0;color:#e1f5fc;line-height:1.6}.selector{display:flex;gap:12px;align-items:end;margin-top:20px;padding:20px;border:1px solid #d5e8ef;border-radius:17px;background:#fff}.selector label{flex:1;font-size:12px;font-weight:850;color:#315968}.selector select{width:100%;margin-top:6px;padding:12px;border:1px solid #bfd9e3;border-radius:10px;background:#fafdff}.selector button{padding:12px 18px;border:0;border-radius:10px;background:#146f91;color:#fff;font-weight:850}.current{display:grid;grid-template-columns:1.1fr .9fr;gap:18px;margin-top:18px}.now,.details,.forecast article{border:1px solid #d5e8ef;border-radius:18px;background:#fff;box-shadow:0 8px 24px #145b780c}.now{display:flex;align-items:center;gap:24px;padding:28px}.icon{font-size:64px}.temp{font-size:54px;font-weight:850;color:#0b6889}.condition{font-size:17px;font-weight:750}.details{display:grid;grid-template-columns:1fr 1fr;gap:1px;overflow:hidden;background:#dcecf2}.details div{padding:20px;background:#fff}.details small{display:block;color:#6d8791}.details strong{display:block;margin-top:4px;font-size:18px}.forecast{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-top:18px}.forecast article{padding:18px;text-align:center}.forecast time{font-weight:850}.forecast .day-icon{display:block;margin:12px;font-size:28px}.notice{margin-top:18px;padding:14px;border-radius:12px;background:#fff5d9;color:#725403;font-size:13px}.source{margin-top:15px;color:#71858c;font-size:11px}.loading{padding:40px;text-align:center}@media(max-width:760px){.selector{display:block}.selector button{width:100%;margin-top:12px}.current{grid-template-columns:1fr}.forecast{grid-template-columns:repeat(2,1fr)}}
</style></head><body><x-public-nav current="weather"/><main class="weather"><section class="hero"><small>INFORMACIÓN PARA TU VIAJE</small><h1>Clima en Loreto</h1><p>Consulta las condiciones antes de viajar. Iquitos aparece por defecto y puedes revisar otras ciudades de Loreto.</p></section><form class="selector" id="weatherForm"><label>Ciudad<select id="location">@foreach($locations as $key=>$place)<option value="{{$key}}" data-lat="{{$place['lat']}}" data-lon="{{$place['lon']}}">{{$place['name']}}, Loreto</option>@endforeach</select></label><button>Actualizar clima</button></form><div id="weatherContent" class="loading">Consultando el clima de Iquitos…</div><p class="notice">⚠ El pronóstico es referencial. Las lluvias, el viento y el nivel de los ríos pueden modificar una salida; confirma siempre con la empresa de transporte.</p><p class="source">Datos meteorológicos: Open-Meteo · Actualización automática.</p></main><x-public-footer/>
<script>
const codes={0:['Despejado','☀️'],1:['Mayormente despejado','🌤️'],2:['Parcialmente nublado','⛅'],3:['Nublado','☁️'],45:['Neblina','🌫️'],48:['Neblina','🌫️'],51:['Llovizna','🌦️'],53:['Llovizna','🌦️'],55:['Llovizna intensa','🌧️'],61:['Lluvia ligera','🌧️'],63:['Lluvia','🌧️'],65:['Lluvia intensa','🌧️'],80:['Chubascos','🌦️'],81:['Chubascos','🌧️'],82:['Chubascos fuertes','⛈️'],95:['Tormenta','⛈️'],96:['Tormenta','⛈️'],99:['Tormenta fuerte','⛈️']};
const form=document.getElementById('weatherForm'),select=document.getElementById('location'),box=document.getElementById('weatherContent');
const info=code=>codes[code]||['Condición variable','🌤️'];const day=date=>new Intl.DateTimeFormat('es-PE',{weekday:'short',day:'2-digit'}).format(new Date(date+'T12:00:00'));
async function loadWeather(){const option=select.selectedOptions[0],name=option.textContent;box.className='loading';box.textContent='Consultando el clima de '+name+'…';try{const url=new URL('https://api.open-meteo.com/v1/forecast');url.search=new URLSearchParams({latitude:option.dataset.lat,longitude:option.dataset.lon,current:'temperature_2m,apparent_temperature,relative_humidity_2m,precipitation,weather_code,wind_speed_10m',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max',timezone:'America/Lima',forecast_days:'5'});const response=await fetch(url);if(!response.ok)throw Error();const data=await response.json(),weather=info(data.current.weather_code);box.className='';box.innerHTML=`<section class="current"><article class="now"><span class="icon">${weather[1]}</span><div><small>${name}</small><div class="temp">${Math.round(data.current.temperature_2m)}°C</div><div class="condition">${weather[0]}</div><small>Sensación de ${Math.round(data.current.apparent_temperature)}°C</small></div></article><article class="details"><div><small>Humedad</small><strong>${data.current.relative_humidity_2m}%</strong></div><div><small>Viento</small><strong>${Math.round(data.current.wind_speed_10m)} km/h</strong></div><div><small>Precipitación</small><strong>${data.current.precipitation} mm</strong></div><div><small>Actualizado</small><strong>${data.current.time.slice(11)} h</strong></div></article></section><section class="forecast">${data.daily.time.map((date,i)=>{const w=info(data.daily.weather_code[i]);return `<article><time>${day(date)}</time><span class="day-icon">${w[1]}</span><strong>${Math.round(data.daily.temperature_2m_max[i])}° / ${Math.round(data.daily.temperature_2m_min[i])}°</strong><small style="display:block;margin-top:7px;color:#66808a">Lluvia ${data.daily.precipitation_probability_max[i]}%</small></article>`}).join('')}</section>`}catch(e){box.className='loading';box.innerHTML='<strong>No pudimos obtener el clima ahora.</strong><br>Intenta nuevamente en unos minutos.'}}
form.addEventListener('submit',e=>{e.preventDefault();loadWeather()});loadWeather();
</script></body></html>
